    "trillion": 1_000_000_000_000,
}


def _numeric_variants(gt: str) -> set[str]:
    """For a GT like '$4.5 billion', return {'4.5', '4,500,000,000', '4500000000', ...}."""
    variants: set[str] = set()
    if not gt:
        return variants
